// Amsi Pro Ultra Font Data & Loader
const AMSI_PRO_ULTRA_BASE64 = '';

(function() {
  try {
    const font = new FontFace('Amsi Pro Ultra', 'url(data:font/ttf;base64,' + AMSI_PRO_ULTRA_BASE64 + ')', {
      weight: '900',
      style: 'normal'
    });
    font.load().then(loadedFont => {
      document.fonts.add(loadedFont);
      console.log('Amsi Pro Ultra font loaded successfully via FontFace API');
      if (typeof renderMasterCanvas === 'function') {
        renderMasterCanvas();
      }
    }).catch(err => {
      console.warn('FontFace API load error:', err);
    });
  } catch (e) {
    console.warn('FontFace error:', e);
  }
})();